"python3 -c "
import os

root_dir = '/Users/m2ultra'
ignore_dirs = {
    'Library', '.Trash', 'node_modules', '.git', '.cache', '.npm', '.cargo', 
    '.rustup', '.local', '.pyenv', '.nvm', 'site-packages', 'venv', '.venv',
    '.antigravity-ide', '.gemini', 'Pods', 'build', 'dist', '.gradle', '.m2'
}

md_files = []

for root, dirs, files in os.walk(root_dir):
    # filter directories in-place
    dirs[:] = [d for d in dirs if d not in ignore_dirs and not d.startswith('.')]
    for f in files:
        if f.lower().endswith('.md'):
            full_path = os.path.join(root, f)
            try:
                size = os.path.getsize(full_path)
                md_files.append((full_path, size))
            except Exception:
                pass

print(f'Total .md files found (excluding caches/hidden/ignored): {len(md_files)}')
for p, s in md_files[:40]:
    print(f'{s:>8} bytes : {p}')
if len(md_files) > 40:
    print(f'... and {len(md_files) - 40} more.')
