import os

volumes = [
    '/Volumes/2TB_SGW',
    '/Volumes/NOIZYWIN',
    '/Volumes/BigSurUSB_2',
    '/Volumes/4TB Lacie',
    '/Volumes/FREDO',
    '/Volumes/12TB'
]

for v in volumes:
    if os.path.exists(v):
        try:
            entries = len(os.listdir(v))
            print(f'[ACCESSIBLE] {v} ({entries} top-level entries)')
        except Exception as e:
            print(f'[ERROR] {v}: {e}')
    else:
        print(f'[NOT MOUNTED] {v}')
