pids = subprocess.check_output(['pgrep', '-P', '7738']).decode().split()
print(f'Active workers ({len(pids)}):')
for p in pids:
    try:
        out = subprocess.check_output(['lsof', '-p', p]).decode(errors='ignore')
        paths = [l for l in out.splitlines() if ('/Volumes/' in l or '/Users/' in l) and 'Python' in l and 'cwd' not in l and 'txt' not in l]
        if paths:
            print(f'  Worker PID {p}: {paths[0]}')
        else:
            print(f'  Worker PID {p}: Staged / Completed')
    except Exception:
        pass
